SELECT COUNT(*) AS total_paid_bookings 
FROM tbl_reservations 
WHERE status = 'enable' AND payment_status = 'paid';

SELECT COUNT(*) AS total_bookings
FROM tbl_reservations
WHERE status = 'enable' AND pickup_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01') AND pickup_date < DATE_FORMAT(CURDATE(), '%Y-%m-31');

SELECT SUM(quote_amount * 0.08) AS tax_amount
FROM tbl_reservations
WHERE id = 2109;
